  // delay; the piece locks on the LOCK_DELAY-th such tick. Moving left/right or pressing soft
  // drop while resting restarts the delay; both share MAX_LOCK_RESETS per piece. Hard drop
  // locks at once.
  var LOCK_DELAY = 2;
  var MAX_LOCK_RESETS = 3;

  // Offsets for each rotation state: ROTATIONS[type][rot] = [[r, c], ...]
  var ROTATIONS = {};
  TYPES.forEach(function (t) {
    var m = SHAPES[t];
    var states = [];
    for (var i = 0; i < 4; i++) {
      var cells = [];
      for (var r = 0; r < m.length; r++) {
        for (var c = 0; c < m.length; c++) {
          if (m[r][c]) cells.push([r, c]);
        }
      }
      states.push(cells);
      m = rotateClockwise(m);
    }
    ROTATIONS[t] = states;
  });

  function rotateClockwise(m) {
    var n = m.length;
    var out = [];
    for (var r = 0; r < n; r++) {
      out.push([]);
      for (var c = 0; c < n; c++) out[r].push(m[n - 1 - c][r]);
    }
    return out;
  }

  // ---- State ----
  var board;        // board[row][col] = piece letter or null (locked cells only)
  var current;      // { type, rot, row, col, lockTicks, lockResets } or null
  var upcoming;     // array of piece letters, soonest first
  var held;         // letter of the held piece, or null
  var canHold;      // false after a hold, until the next piece locks
  var bag;          // 7-bag for the random generator
  var score, level, lines, status;
  var timer = null;

  function emptyBoard() {
    var b = [];
    for (var r = 0; r < ROWS; r++) {
      var row = [];
      for (var c = 0; c < COLS; c++) row.push(null);
      b.push(row);
    }
    return b;
  }

  function randomPiece() {
    if (!bag || bag.length === 0) {
      bag = TYPES.slice();
      for (var i = bag.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
      }
