  function pieceCells(p, rot, row, col) {
    return ROTATIONS[p.type][rot].map(function (o) { return [row + o[0], col + o[1]]; });
  }

  function fits(p, rot, row, col) {
    var cells = pieceCells(p, rot, row, col);
    for (var i = 0; i < cells.length; i++) {
