  // Restarts the lock delay of a resting piece, at most MAX_LOCK_RESETS times per piece.
  function restartLockDelay() {
    if (current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets++;
      current.lockTicks = 0;
