  // instead, the same as a sideways move. It spends a reset only once the delay has started,
  // so a held down key does not burn the budget the moment the piece lands.
  function softDrop() {
    if (tryMove(1, 0)) score += SOFT_DROP_POINTS;
    else if (current.lockTicks > 0) restartLockDelay();
  }

  // Clockwise rotation. If the rotated shape does not fit in place, try sideways shifts only
  // (a vertical kick would let a resting piece climb and stay in the air). If nothing fits,
  // the piece is left untouched. A shape that would stick out above the board is pushed down
  // into it, so a just-spawned I piece can stand upright.
  function tryRotateCW() {
    if (!current) return false;
    var rot = (current.rot + 1) % 4;
    var top = Math.min.apply(null, ROTATIONS[current.type][rot].map(function (o) { return o[0]; }));
    var row = Math.max(current.row, -top);
    var kicks = [0, -1, 1, -2, 2];
    for (var i = 0; i < kicks.length; i++) {
