    ArrowLeft: "left",
    ArrowRight: "right",
    ArrowDown: "softDrop",
    ArrowUp: "rotateCW",
    x: "rotateCW",
    X: "rotateCW",
    " ": "hardDrop",
    c: "hold",
    C: "hold",
